sketches.source:
setcpm(70/4)
song("entrance@4 hall@8 lair@8 hall'@4 retreat@4", "once")
tempomap("0:17.5 24:17.5 28:12")

// The form: the entrance, the hall, the beast's lair, the hall again an octave lower
// and a retreat that slows to a stop (about 1 min 40 s)

// Water dripping from every direction in a stone hall
drips: s("drip*8?0.6").azimuth(rand.range(-180, 180)).distance(3).seed("dungeon")
  .space("church").gain(rand.range(.06, .16))

// A torch on each wall
torchL: s("fire").slow(4).intensity(.3).density(8).azimuth(-80).distance(2).gain(.14)
torchR: s("fire").slow(4).intensity(.3).density(8).azimuth(80).distance(2).gain(.14)

// In the lair something large breathes as it circles you in the dark, once in eight bars
beast: s("engine").slow(8).lpf(250).azimuth(saw.range(-180, 180).slow(8))
  .distance(5).posglide(.5).gain(.12).sections("lair")

// Your own footsteps, just behind you; you freeze while the beast circles
steps: s("step ~ step ~").azimuth(180).distance(1).lpf(1500).gain(.12)
  .exceptSections("lair")

// irate turns the drone's phase between the ears, a quarter or half a turn a second
drone: note("[d2,a2]").slow(4).s("sawtooth").irate("<.25 .5>")
  .lpf(500).attack(2).sustain(1).release(3).gain(.18)

// A hesitant melody, deep in the stone and centred; on the way back it sinks an octave
melody: n("<[0 ~ 2 ~] [1 ~ ~ -1] [0 ~ 4 3] [2@4]>").scale("D:harmonic minor").transpose(12)
  .s("triangle").timbre("hollow").attack(.05).decay(.8).sustain(.2).release(1)
  .space("church").room(.6).gain(.2)
  .sections("hall").variant(x => x.add(-12).room(.8))

setcpm(96/4)
song("vents@4 (patrol@8 1.hide@4 2.alert@4)*2 escape@8 outro@4", "once")
tempomap("0:24 36:24 40:18")

// The form: the vents, two patrols (you hide after the first and trip an alert after the second),
// an escape and an outro that slows to a stop (about 1 min 40 s)

// The vents: unrelated noise in each ear, a wide hush all around
air: s("pink").slow(8).icorr(.1).hpf(300).lpf(2500).gain(.04)

// A sonar ping from a new direction each bar: ahead, right, behind, left
sonar: note("e5 ~ ~ ~").s("sine").fm(1.5).fmh(2).decay(1.5).sustain(0).release(2)
  .azimuth("<0 90 180 -90>").distance(4).room(.5).gain(.1)

// Guards pacing beyond the walls, left and right, until you escape
guard1: s("step ~ step ~").azimuth(-100).distance(4).occlude(.6).gain(.14)
  .sections("patrol hide alert")
guard2: s("~ step ~ step").azimuth(110).distance(6).occlude(.6).gain(.1)
  .sections("patrol hide alert")

// A low-pass on each ear alone, sweeping in opposite directions every four bars
bass: note("e1 ~ e1 ~ g1 ~ e1 [~ f1]").s("sawtooth").lpq(5)
  .lcutoff(saw.range(200, 1600).slow(4)).rcutoff(isaw.range(200, 1600).slow(4))
  .decay(.2).sustain(.3).release(.1).gain(.38).exceptSections("vents hide outro")

// A muted, centred kit that falls silent while you hide, and a tense pad with a high-pass
// on the right ear only
drums: s("bd ~ ~ bd ~ ~ ~ ~, ~ ~ rim ~ ~ ~ rim ~").lpf(3000).gain(bysec("escape:.4 *:.32"))
  .exceptSections("vents hide outro").atEnd(1, x => x.ply(2))
pad: note("<[e3,g3,b3] [c3,e3,a3]>").slow(2).s("triangle").rhcutoff(1200)
  .attack(1).sustain(1).release(2).room(.5).gain(.14)

setcpm(156/4)
song("warning@8 (fight@8 1.clash@4 2.rage@4)*2 second@8 fight'@8 fight''@8 finale@4", "once")
tempomap("0:39 56:39 60:26")

// The form: a warning, the fight twice with a different break each pass, the boss's second form,
// two harder fights and a finale that slows to a stop (about 1 min 35 s)

// The floor of the arena: centred drums and bass, with a fill closing each section
drums: stack(
  s("bd*4").shape(.3).gain(.8),
  s("~ sd ~ [sd sd]").room(.3).gain(.55),
  s("hh*16").hpf(8000).gain("[.25 .1]*8")
).exceptSections("warning").atEnd(1, x => x.ply(2))
bass: note("e1 e1 f1 e1 g1 e1 f1 d1").s("sawtooth").lpf(900).lpq(4)
  .decay(.12).sustain(.3).release(.05).gain(.45).exceptSections("warning")

// irate turns the lead's phase between the ears, one or two turns a second, below 3 Hz
// The second fight is brighter, the third an octave higher
lead: n("<[0 1 4 3 4@2 7 6] [7 6 4 3 1@2 0 1] [4 5 7 8 7@2 5 4] [3 1 0 -1 0@4]>").scale("E:phrygian").transpose(12)
  .s("sawtooth").unison(2).detune(.15).irate("<1 2>")
  .lpf(3000).attack(.01).sustain(.6).release(.1).gain(.18)
  .sections("fight").variant(x => x.lpf(4500), x => x.add(12).lpf(5000).gain(.14))

// From about 1 to 30 ms the stabs stay on the leading side but grow wider each bar
stabs: note("[e3,g3,b3,e4]").struct("x ~ ~ x ~ ~ x ~").s("sawtooth").unison(4).detune(.3)
  .itd("<1 8 15 25>").lpf(3500).decay(.25).sustain(0).room(.4).gain(.2)

// Under about 0.7 ms the delay moves a sound sideways: the alarm swings every fourth bar
alarm: note("<~ ~ ~ [b4 e5 b4 e5]>").s("square").pw(.3)
  .itd(sine.range(-.6, .6).fast(2)).decay(.2).sustain(.4).gain(.1)

setcpm(100/4)
song("search@4 (find@8 1.look@4 2.open@4)*2 hoard@8 leave@4", "once")
tempomap("0:25 36:25 40:18")

// The form: a search, the secret found twice with a pause after each, the hoard
// and a departure that slows to a stop (about 1 min 40 s)

// The same noise feeds both ears, but one ear's noise is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear the jingle: C, Dm, Em, C
secret: s("white*4").dichotic("<[523 659 784 1047] [587 698 880 1175] [659 784 988 1319] [1047@4]>")
  .dichoticq(30).attack(.01).sustain(1).release(.05).gain(.16)
  .sections("find hoard")

// A quiet hint: the first bar on a chip pulse, once every four bars
hint: note("<[c5 e5 g5 c6] ~ ~ ~>").s("square").pw(.25)
  .decay(.1).sustain(.3).release(.05).gain(.07).sections("search find")

// Treasure sparkles placed around you, a little above, brightest in the hoard
sparkle: n(irand(8).segment(8)).scale("C:major pentatonic").transpose(24)
  .degradeBy(.6).seed("treasure")
  .s("triangle").timbre("glass").decay(.15).sustain(0)
  .azimuth(rand.range(-150, 150)).elevation(30).distance(2)
  .gain(bysec("hoard:.12 *:.08")).exceptSections("search")

// A soft pad holding the chords
pad: note("<[c3,e3,g3] [d3,f3,a3] [e3,g3,b3] [c3,e3,g3]>").s("sawtooth").unison(3).detune(.2)
  .attack(.5).sustain(.8).release(1).lpf(1200).room(.6).gain(.1)

setcpm(60/3)
song("rest@4 save@8 save'@8 dream@4 save''@8 wake@4", "once")
tempomap("0:20 32:20 36:14")

// One cycle is a bar of 3/4
// The form: rest, the save theme, the theme an octave lower, a dream, the theme floating higher
// and a waking phrase that slows to a stop (about 1 min 50 s)

// A 2 Hz binaural drone: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("[c2,g2]").slow(4).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.24)

// The save theme on a music box, floating above your head: C, G, F, C, C, G, C, C
// The first variation sinks an octave, the second floats higher and further away
musicbox: note("<[e5 g5 c6] [b5@2 g5] [a5 f5 a5] [g5@3] [e5 g5 c6] [d6@2 b5] [c6 g5 e5] [c6@3]>")
  .s("sine").fm(2).fmh(4).attack(.002).decay(1).sustain(0).release(1.5)
  .elevation(40).distance(2).room(.6).size(.85).gain(.2)
  .sections("save wake").variant(x => x.add(-12), x => x.elevation(70).distance(3))

// A soft root on each downbeat
bass: note("<c2 g1 f1 c2 c2 g1 c2 c2>").s("triangle").timbre("soft")
  .attack(.01).decay(1).sustain(0).release(1).gain(.2).exceptSections("rest")

// A healing shimmer circling you slowly, and a campfire to one side
shimmer: n(irand(6).segment(3)).scale("C:major pentatonic").transpose(24)
  .degradeBy(.5).seed("save")
  .s("triangle").timbre("glass").decay(.8).sustain(0).release(1)
  .azimuth(saw.range(-180, 180).slow(8)).distance(2).posglide(.4).gain(.07)
fire: s("fire").slow(4).intensity(.2).density(4).azimuth(-40).distance(3).gain(.12)
